Looking at this logic puzzle, I need to find who lives in the blue house by checking all the constraints.

Let me analyze some key clues:
- Clue 8: Harper drinks tea
- Clue 13: Quinn lives immediately to the left of the person who drinks tea
- Clue 3: The horse owner lives immediately to the left of the person who drinks tea
- Clue 7: The horse owner lives immediately to the left of the person in the blue house

From clues 3 and 13: Quinn owns a horse and is immediately left of Harper
From clues 3 and 7: Harper must live in the blue house (since the horse owner Quinn is immediately to the left)

I'll write a constraint satisfaction solver that exhaustively checks all valid configurations:

```python
from itertools import permutations

def is_valid(houses):
    def find_index(attr, value):
        for i in range(5):
            if houses[i][attr] == value:
                return i
        return -1

    def find_indices(attr, value):
        return [i for i in range(5) if houses[i][attr] == value]

    # Clue 1
    if find_index('color', 'white') >= 0 and houses[find_index('color', 'white')]['name'] == 'Sawyer':
        return False

    # Clue 2
    orange_idx = find_index('color', 'orange')
    if orange_idx >= 0 and houses[orange_idx]['hobby'] != 'hiking':
        return False

    # Clue 3
    if not any(houses[i]['pet'] == 'horse' and houses[i+1]['drink'] == 'tea' for i in range(4)):
        return False

    # Clue 4
    milk_idx = find_index('drink', 'milk')
    if milk_idx >= 0 and orange_idx >= 0 and milk_idx == orange_idx:
        return False

    # Clue 5
    jordan_idx, blue_idx = find_index('name', 'Jordan'), find_index('color', 'blue')
    if jordan_idx < 0 or blue_idx < 0 or abs(jordan_idx - blue_idx) != 1:
        return False

    # Clue 6
    juice_idx, chess_idx = find_index('drink', 'juice'), find_index('hobby', 'chess')
    if juice_idx >= 0 and chess_idx >= 0 and juice_idx != chess_idx:
        return False

    # Clue 7
    if not any(houses[i]['pet'] == 'horse' and houses[i+1]['color'] == 'blue' for i in range(4)):
        return False

    # Clue 8
    tea_idx = find_index('drink', 'tea')
    if tea_idx >= 0 and houses[tea_idx]['name'] != 'Harper':
        return False

    # Clue 9
    if jordan_idx >= 0 and orange_idx >= 0 and jordan_idx == orange_idx:
        return False

    # Clue 10
    sawyer_idx, cat_idx = find_index('name', 'Sawyer'), find_index('pet', 'cat')
    if sawyer_idx < 0 or cat_idx < 0 or abs(sawyer_idx - cat_idx) != 1:
        return False

    # Clue 11
    if not any(houses[i]['pet'] == 'bird' and houses[i+1]['color'] == 'green' for i in range(4)):
        return False

    # Clue 12
    if not any(houses[i]['name'] == 'Riley' and houses[i+1]['hobby'] == 'baking' for i in range(4)):
        return False

    # Clue 13
    if not any(houses[i]['name'] == 'Quinn' and houses[i+1]['drink'] == 'tea' for i in range(4)):
        return False

    # Clue 14
    if not any(abs(find_indices('hobby', 'fencing')[0] - orange_idx) == 1 if find_indices('hobby', 'fencing') and orange_idx >= 0 else False for _ in [1]):
        fencing_idx = find_index('hobby', 'fencing')
        if fencing_idx < 0 or orange_idx < 0 or abs(fencing_idx - orange_idx) != 1:
            return False

    # Clue 15
    rabbit_idx = find_index('pet', 'rabbit')
    if rabbit_idx < 0 or orange_idx < 0 or abs(rabbit_idx - orange_idx) != 1:
        return False

    # Clue 16
    if not any(houses[i]['drink'] == 'water' and houses[i+1]['color'] == 'green' for i in range(4)):
        return False

    return True

colors = ['blue', 'green', 'orange', 'white', 'yellow']
pets = ['bird', 'cat', 'dog', 'horse', 'rabbit']
drinks = ['coffee', 'juice', 'milk', 'tea', 'water']
hobbies = ['baking', 'chess', 'fencing', 'hiking', 'painting']

for quinn_pos in range(4):
    harper_pos = quinn_pos + 1
    remaining = ['Jordan', 'Riley', 'Sawyer']
    remaining_pos = [i for i in range(5) if i not in [quinn_pos, harper_pos]]

    for perm in permutations(remaining):
        positions = [None] * 5
        positions[quinn_pos] = 'Quinn'
        positions[harper_pos] = 'Harper'
        for i, person in enumerate(perm):
            positions[remaining_pos[i]] = person

        for color_perm in permutations(colors):
            for pet_perm in permutations(pets):
                for drink_perm in permutations(drinks):
                    for hobby_perm in permutations(hobbies):
                        houses = [{'name': positions[i], 'color': color_perm[i], 'pet': pet_perm[i], 'drink': drink_perm[i], 'hobby': hobby_perm[i]} for i in range(5)]

                        if houses[harper_pos]['color'] != 'blue' or houses[harper_pos]['drink'] != 'tea' or houses[quinn_pos]['pet'] != 'horse':
                            continue

                        if is_valid(houses):
                            for house in houses:
                                if house['color'] == 'blue':
                                    print(f"ANSWER: {house['name']}")
                                    exit()
